package com.sleekydz86.storagemigration.global.jdbc;

public enum SqlDialect {

    ORACLE("VARCHAR2(%d)", "NUMBER(19)", "BLOB", "TIMESTAMP", "",
            "NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY"),
    MYSQL("VARCHAR(%d)", "BIGINT", "LONGBLOB", "DATETIME(6)", " DEFAULT CHARSET=utf8mb4",
            "BIGINT AUTO_INCREMENT PRIMARY KEY"),
    POSTGRESQL("VARCHAR(%d)", "BIGINT", "BYTEA", "TIMESTAMP", "",
            "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY");

    private final String varcharPattern;
    private final String bigintType;
    private final String blobType;
    private final String timestampType;
    private final String tableSuffix;
    private final String identityColumn;

    SqlDialect(String varcharPattern, String bigintType, String blobType, String timestampType, String tableSuffix,
               String identityColumn) {
        this.varcharPattern = varcharPattern;
        this.bigintType = bigintType;
        this.blobType = blobType;
        this.timestampType = timestampType;
        this.tableSuffix = tableSuffix;
        this.identityColumn = identityColumn;
    }

    public String varchar(int length) {
        return varcharPattern.formatted(length);
    }

    public String bigint() {
        return bigintType;
    }

    public String blob() {
        return blobType;
    }

    public String timestamp() {
        return timestampType;
    }

    public String tableSuffix() {
        return tableSuffix;
    }

    public String identity() {
        return identityColumn;
    }

    public String limit(String sql, int rows) {
        return switch (this) {
            case ORACLE -> sql + " FETCH FIRST " + rows + " ROWS ONLY";
            case MYSQL, POSTGRESQL -> sql + " LIMIT " + rows;
        };
    }
}
